#!/usr/bin/env python3
"""
Round 208o (culprits), 14 October 2026. Needs round 207o.

Bioluminescent first; points in each basemap's own colours as firmer glow orbs.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 208o (14 October)\n\nNeeds round 207o (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- Bioluminescent is the opening basemap.\n- Points keep their glow orbs, firmer (core blur 0.35, haze 0.22), in the\n  owner\'s colour for each basemap by default ("Suit basemap", now the\n  default theme, LAYER_THEMES.auto with palette: true):\n  Bioluminescent 61,194,172; Woodlands 61,178,194; Atlas 255,255,255;\n  Jurassic 117,165,189; Hologram 71,175,255; Hell 255,0,0; Standard\n  255,255,255. One point layer on: that colour. More: each takes a\n  neighbouring colour of the family (paletteFor; no orange, yellow or\n  green), in the order turned on. A layer with several kinds of point, or a\n  ramp, takes shades of its colour (paletteShades). Keys under the rows and\n  in the legend follow (paletteKeys). Shapes and national highlights stay\n  muted. Colour the points by, the colour squares and Layer colours work as\n  before; picking any other theme leaves the palette.\n\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round208o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 207o" not in h.read_text(encoding="utf-8"):
        sys.exit("round208o: round 207o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round208o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/index.html", "map/bodies.html", "map/test.mjs", "map/atlas-plate.webp", check=False)
            sys.exit("round208o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round208o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
